module tb;

    // 1. Declare inputs as regs, outputs as wires
    reg        clk;
    reg        areset;
    reg        load;
    reg        ena;
    reg  [3:0] data;
    wire [3:0] q;

    // 2. Instantiate TopModule dut ( ... );
    TopModule dut (
        .clk    (clk),
        .areset (areset),
        .load   (load),
        .ena    (ena),
        .data   (data),
        .q      (q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    reg [3:0] expected_q;

    // Task to check outputs using 4-state case inequality
    task check_output(input [3:0] exp);
        begin
            #1; // Small delay to sample after clock edge
            if (q !== exp) begin
                $display("Mismatch at time %0t: q = %b, expected = %b", $time, q, exp);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        load = 0;
        ena = 0;
        data = 4'b0000;
        expected_q = 4'b0000;

        // Test 1: Asynchronous reset
        #2;
        areset = 1;
        expected_q = 4'b0000;
        check_output(expected_q);

        #7;
        areset = 0;
        check_output(expected_q);

        // Test 2: Load data
        @(posedge clk);
        #2;
        load = 1;
        ena = 0;
        data = 4'b1011;
        expected_q = 4'b1011;

        @(posedge clk);
        check_output(expected_q);

        // Test 3: Disable load, hold value (ena = 0)
        #2;
        load = 0;
        ena = 0;

        @(posedge clk);
        check_output(expected_q);

        // Test 4: Enable shift right (q should become {1'b0, q[3:1]})
        // Current q = 4'b1011 -> Expected after shift: 4'b0101
        #2;
        ena = 1;
        expected_q = 4'b0101;

        @(posedge clk);
        check_output(expected_q);

        // Test 5: Shift right again
        // Current q = 4'b0101 -> Expected after shift: 4'b0010
        expected_q = 4'b0010;
        @(posedge clk);
        check_output(expected_q);

        // Test 6: Priority check (load and ena both high -> load wins)
        #2;
        load = 1;
        ena = 1;
        data = 4'b1100;
        expected_q = 4'b1100;

        @(posedge clk);
        check_output(expected_q);

        // Test 7: Shift after priority load
        #2;
        load = 0;
        ena = 1;
        expected_q = 4'b0110;

        @(posedge clk);
        check_output(expected_q);

        // Final report
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
